import {randomString,sha256Base64Url,currentSupabaseUser,scToken,scFetch} from "./creator-services.js";
const corsHeaders={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Methods":"GET,POST,OPTIONS","Access-Control-Allow-Headers":"Authorization, Content-Type, X-Telegram-Bot-Api-Secret-Token, X-Nexora-Setup-Secret"};
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{...corsHeaders,"Content-Type":"application/json; charset=utf-8"}});
function randomToken(bytes=32){const b=new Uint8Array(bytes);crypto.getRandomValues(b);return btoa(String.fromCharCode(...b)).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");}
function authError(code,message=""){const e=new Error(message||code);e.authCode=code;return e;}
function classify(e){if(e?.authCode)return e.authCode;const s=String(e?.message||e||"");if(s.includes("AUTH_UNAUTHORIZED"))return"AUTH_UNAUTHORIZED";if(s.includes("SOUNDCLOUD_CONFIG_MISSING"))return"AUTH_CONFIG_ERROR";if(s.includes("SOUNDCLOUD_"))return"SOUNDCLOUD_ERROR";if(s.includes("SUPABASE_CONFIG_MISSING")||s.includes("_MISSING"))return"AUTH_CONFIG_ERROR";if(s.includes("ACCOUNT_EXISTS"))return"AUTH_ACCOUNT_EXISTS";if(s.includes("ACCOUNT_NOT_FOUND"))return"AUTH_ACCOUNT_NOT_FOUND";if(s.includes("Supabase"))return"AUTH_DATABASE_ERROR";return"AUTH_DATABASE_ERROR";}
async function hmacPassword(env,id){if(!env.TELEGRAM_AUTH_SECRET)throw authError("AUTH_CONFIG_ERROR","TELEGRAM_AUTH_SECRET_MISSING");const k=await crypto.subtle.importKey("raw",new TextEncoder().encode(env.TELEGRAM_AUTH_SECRET),{name:"HMAC",hash:"SHA-256"},false,["sign"]);const s=await crypto.subtle.sign("HMAC",k,new TextEncoder().encode(String(id)));return btoa(String.fromCharCode(...new Uint8Array(s))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"")+"N9!";}
async function sb(env,path,init={}){if(!env.SUPABASE_URL||!env.SUPABASE_SERVICE_ROLE_KEY)throw authError("AUTH_CONFIG_ERROR","SUPABASE_CONFIG_MISSING");const r=await fetch(env.SUPABASE_URL+path,{...init,headers:{apikey:env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,"Content-Type":"application/json",...(init.headers||{})}});const t=await r.text();if(!r.ok)throw authError("AUTH_DATABASE_ERROR",`Supabase ${r.status}: ${t}`);return t?JSON.parse(t):null;}
async function tg(env,method,body={}){if(!env.TELEGRAM_BOT_TOKEN)throw authError("AUTH_CONFIG_ERROR","TELEGRAM_BOT_TOKEN_MISSING");const r=await fetch(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/${method}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();if(!d.ok)throw new Error(`Telegram ${method}: ${d.description||"failed"}`);return d.result;}
async function authAdmin(env,email,password,meta){const r=await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users`,{method:"POST",headers:{apikey:env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,"Content-Type":"application/json"},body:JSON.stringify({email,password,email_confirm:true,user_metadata:meta})});const t=await r.text();let data=null;try{data=t?JSON.parse(t):null}catch{}return{ok:r.ok,status:r.status,data};}
async function findAuthUser(env,email){const r=await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users?page=1&per_page=1000`,{headers:{apikey:env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`}});const t=await r.text();if(!r.ok)throw authError("AUTH_DATABASE_ERROR",`Supabase admin list ${r.status}: ${t}`);const d=JSON.parse(t);return(d.users||[]).find(u=>u.email===email)||null;}
async function createSession(env,email,password){const r=await fetch(`${env.SUPABASE_URL}/auth/v1/token?grant_type=password`,{method:"POST",headers:{apikey:env.SUPABASE_SERVICE_ROLE_KEY,"Content-Type":"application/json"},body:JSON.stringify({email,password})});const t=await r.text();if(!r.ok)throw authError("AUTH_DATABASE_ERROR",`Supabase auth ${r.status}: ${t}`);return JSON.parse(t);}
async function ensureUser(env,tgUser,action){const tid=String(tgUser.id),email=`telegram_${tid}@accounts.nexora.local`,password=await hmacPassword(env,tid),display=String([tgUser.first_name,tgUser.last_name].filter(Boolean).join(" ")||tgUser.username||`user_${tid}`).slice(0,80),username=`tg_${tid}`;let accounts=await sb(env,`/rest/v1/telegram_accounts?select=*&telegram_id=eq.${encodeURIComponent(tid)}&limit=1`);let userId=accounts[0]?.user_id;if(action==="login"&&!userId)throw authError("AUTH_ACCOUNT_NOT_FOUND");if(action==="register"&&userId)throw authError("AUTH_ACCOUNT_EXISTS");if(!userId){const created=await authAdmin(env,email,password,{telegram_id:tid,telegram_username:tgUser.username||null});if(created.ok)userId=created.data?.id;else if(created.status===422||/already|exists|duplicate/i.test(JSON.stringify(created.data||{}))){const existing=await findAuthUser(env,email);if(!existing)throw authError("AUTH_DATABASE_ERROR","existing user not found");userId=existing.id;}else throw authError("AUTH_DATABASE_ERROR",`Supabase admin ${created.status}`);if(!userId)throw authError("AUTH_DATABASE_ERROR","Supabase admin did not return user id");}const profile=await sb(env,`/rest/v1/profiles?select=id,profile_type&id=eq.${encodeURIComponent(userId)}&limit=1`);if(!profile.length)await sb(env,"/rest/v1/profiles",{method:"POST",headers:{Prefer:"return=minimal"},body:JSON.stringify({id:userId,username,display_name:display,profile_type:"user"})});else await sb(env,`/rest/v1/profiles?id=eq.${encodeURIComponent(userId)}`,{method:"PATCH",headers:{Prefer:"return=minimal"},body:JSON.stringify({display_name:display,updated_at:new Date().toISOString()})});if(!accounts.length)await sb(env,"/rest/v1/telegram_accounts",{method:"POST",headers:{Prefer:"return=minimal"},body:JSON.stringify({telegram_id:tid,user_id:userId,username:tgUser.username||null,display_name:display})});else await sb(env,`/rest/v1/telegram_accounts?telegram_id=eq.${encodeURIComponent(tid)}`,{method:"PATCH",headers:{Prefer:"return=minimal"},body:JSON.stringify({user_id:userId,username:tgUser.username||null,display_name:display,updated_at:new Date().toISOString()})});return{userId,session:await createSession(env,email,password)};}
async function patchChallenge(env,c,p){await sb(env,`/rest/v1/telegram_auth_challenges?challenge=eq.${encodeURIComponent(c)}`,{method:"PATCH",headers:{Prefer:"return=minimal"},body:JSON.stringify(p)});}
async function webhook(req,env){if(env.TELEGRAM_WEBHOOK_SECRET&&req.headers.get("X-Telegram-Bot-Api-Secret-Token")!==env.TELEGRAM_WEBHOOK_SECRET)return json({error:"forbidden"},403);const u=await req.json(),m=u.message;if(!m?.from||typeof m.text!=="string")return json({ok:true});const match=m.text.trim().match(/^\/start(?:@[^\s]+)?(?:\s+([A-Za-z0-9_-]{20,64}))?$/);if(!match?.[1]){await tg(env,"sendMessage",{chat_id:m.chat.id,text:"Добро пожаловать в Nexora. Откройте приложение и выберите «Войти» или «Регистрация»."});return json({ok:true});}const c=match[1],rows=await sb(env,`/rest/v1/telegram_auth_challenges?select=*&challenge=eq.${encodeURIComponent(c)}&status=eq.pending&limit=1`);if(!rows.length){await tg(env,"sendMessage",{chat_id:m.chat.id,text:"Ссылка Nexora недействительна или уже использована. Начните авторизацию заново в приложении."});return json({ok:true});}const ch=rows[0];if(new Date(ch.expires_at).getTime()<Date.now()){await patchChallenge(env,c,{status:"expired"});await tg(env,"sendMessage",{chat_id:m.chat.id,text:"Ссылка Nexora истекла. Начните авторизацию заново."});return json({ok:true});}try{const r=await ensureUser(env,m.from,ch.action);await patchChallenge(env,c,{status:"approved",telegram_id:m.from.id,telegram_username:m.from.username||null,display_name:[m.from.first_name,m.from.last_name].filter(Boolean).join(" ").slice(0,80),access_token:r.session.access_token,refresh_token:r.session.refresh_token});await tg(env,"sendMessage",{chat_id:m.chat.id,text:"Telegram подтверждён. Вернитесь в Nexora — вход будет завершён автоматически."});}catch(e){const code=classify(e);console.error("Telegram auth failed",{code,challenge:c,telegram_id:m.from.id,message:String(e?.message||e)});const text={AUTH_CONFIG_ERROR:"Ошибка конфигурации Nexora. Обратитесь к администратору.",AUTH_DATABASE_ERROR:"Не удалось обратиться к серверу Nexora. Попробуйте ещё раз через некоторое время.",AUTH_ACCOUNT_EXISTS:"Аккаунт Nexora уже существует. Выберите «Войти» в приложении.",AUTH_ACCOUNT_NOT_FOUND:"Аккаунт Nexora ещё не зарегистрирован. Выберите «Регистрация» в приложении."}[code]||"Не удалось завершить авторизацию. Попробуйте ещё раз.";if(code==="AUTH_ACCOUNT_EXISTS"||code==="AUTH_ACCOUNT_NOT_FOUND")await patchChallenge(env,c,{status:"rejected"});await tg(env,"sendMessage",{chat_id:m.chat.id,text:`${text}\n\nКод: ${code}`});}return json({ok:true});}
async function setup(req,env){if(!env.TELEGRAM_AUTH_SECRET||req.headers.get("X-Nexora-Setup-Secret")!==env.TELEGRAM_AUTH_SECRET)return json({error:"forbidden"},403);if(!env.TELEGRAM_WEBHOOK_SECRET)return json({error:"TELEGRAM_WEBHOOK_SECRET_MISSING"},500);const url=new URL(req.url),w=`${url.origin}/telegram/webhook`;await tg(env,"setWebhook",{url:w,secret_token:env.TELEGRAM_WEBHOOK_SECRET,allowed_updates:["message"],drop_pending_updates:true});return json({ok:true,webhook:w});}
async function debug(env){const checks={supabase_url:Boolean(env.SUPABASE_URL),supabase_service_role:Boolean(env.SUPABASE_SERVICE_ROLE_KEY),telegram_bot_token:Boolean(env.TELEGRAM_BOT_TOKEN),telegram_auth_secret:Boolean(env.TELEGRAM_AUTH_SECRET),telegram_webhook_secret:Boolean(env.TELEGRAM_WEBHOOK_SECRET),soundcloud_client_id:Boolean(env.SOUNDCLOUD_CLIENT_ID),soundcloud_client_secret:Boolean(env.SOUNDCLOUD_CLIENT_SECRET),soundcloud_redirect_uri:Boolean(env.SOUNDCLOUD_REDIRECT_URI)};return json({ok:Object.values(checks).every(Boolean),checks});}
async function soundcloudConnect(req,env){const user=await currentSupabaseUser(req,env);if(!env.SOUNDCLOUD_CLIENT_ID||!env.SOUNDCLOUD_CLIENT_SECRET||!env.SOUNDCLOUD_REDIRECT_URI)return json({error:"SOUNDCLOUD_CONFIG_MISSING"},503);const verifier=randomString(48),challenge=await sha256Base64Url(verifier),state=randomToken(32),expires=new Date(Date.now()+10*60*1000).toISOString();await sb(env,"/rest/v1/soundcloud_oauth_states",{method:"POST",headers:{Prefer:"return=minimal"},body:JSON.stringify({state,user_id:user.id,code_verifier:verifier,expires_at:expires})});const q=new URLSearchParams({client_id:env.SOUNDCLOUD_CLIENT_ID,redirect_uri:env.SOUNDCLOUD_REDIRECT_URI,response_type:"code",code_challenge:challenge,code_challenge_method:"S256",state,display:"popup"});return json({authorize_url:`https://secure.soundcloud.com/authorize?${q}`});}
async function soundcloudCallback(req,env){const u=new URL(req.url),code=u.searchParams.get("code"),state=u.searchParams.get("state"),error=u.searchParams.get("error");if(error)return new Response(`<html><body><h2>Nexora</h2><p>SoundCloud authorization was cancelled.</p></body></html>`,{headers:{"Content-Type":"text/html; charset=utf-8"}});if(!code||!state)return new Response("Missing code or state",{status:400});const rows=await sb(env,`/rest/v1/soundcloud_oauth_states?select=*&state=eq.${encodeURIComponent(state)}&limit=1`);if(!rows.length||new Date(rows[0].expires_at).getTime()<Date.now())return new Response("Authorization expired",{status:400});const st=rows[0];const tok=await scToken(env,{grant_type:"authorization_code",client_id:env.SOUNDCLOUD_CLIENT_ID,client_secret:env.SOUNDCLOUD_CLIENT_SECRET,redirect_uri:env.SOUNDCLOUD_REDIRECT_URI,code_verifier:st.code_verifier,code});const me=await scFetch(tok.access_token,"/me");const tracks=await scFetch(tok.access_token,"/me/tracks?limit=50&linked_partitioning=true");const expiresAt=new Date(Date.now()+Number(tok.expires_in||3600)*1000).toISOString();await sb(env,"/rest/v1/soundcloud_connections",{method:"POST",headers:{Prefer:"resolution=merge-duplicates,return=minimal"},body:JSON.stringify({user_id:st.user_id,soundcloud_user_id:String(me.id??me.urn??me.username),username:me.username||null,permalink_url:me.permalink_url||null,avatar_url:me.avatar_url||null,access_token:tok.access_token,refresh_token:tok.refresh_token||null,expires_at:expiresAt,scope:tok.scope||null,updated_at:new Date().toISOString()})});const list=Array.isArray(tracks?.collection)?tracks.collection:[];await sb(env,`/rest/v1/soundcloud_tracks?user_id=eq.${encodeURIComponent(st.user_id)}`,{method:"DELETE"});if(list.length)await sb(env,"/rest/v1/soundcloud_tracks",{method:"POST",headers:{Prefer:"return=minimal"},body:JSON.stringify(list.map((t,i)=>({user_id:st.user_id,soundcloud_track_id:String(t.id??t.urn),urn:t.urn||null,title:t.title||"Untitled",permalink_url:t.permalink_url||null,artwork_url:t.artwork_url||null,duration_ms:t.duration||null,playback_count:t.playback_count||0,genre:t.genre||null,created_at:t.created_at||null,position:i,synced_at:new Date().toISOString()})))});await sb(env,`/rest/v1/soundcloud_oauth_states?state=eq.${encodeURIComponent(state)}`,{method:"DELETE"});return new Response(`<html><head><meta name="viewport" content="width=device-width"></head><body style="font-family:sans-serif;background:#040a13;color:white;text-align:center;padding:48px"><h2>SoundCloud подключён</h2><p>Вернитесь в Nexora. Треки уже синхронизируются.</p></body></html>`,{headers:{"Content-Type":"text/html; charset=utf-8"}});}
async function soundcloudStatus(req,env){const user=await currentSupabaseUser(req,env);const c=await sb(env,`/rest/v1/soundcloud_connections?select=soundcloud_user_id,username,permalink_url,avatar_url,expires_at,scope&user_id=eq.${encodeURIComponent(user.id)}&limit=1`);const tracks=await sb(env,`/rest/v1/soundcloud_tracks?select=soundcloud_track_id,urn,title,permalink_url,artwork_url,duration_ms,playback_count,genre,created_at,position&user_id=eq.${encodeURIComponent(user.id)}&order=position.asc&limit=50`);return json({connected:Boolean(c.length),connection:c[0]||null,tracks});}
async function beatchainConnect(req,env){const user=await currentSupabaseUser(req,env),b=await req.json(),url=String(b.profile_url||"").trim();if(!/^https?:\/\/(www\.)?beatchain\.com\//i.test(url))return json({error:"INVALID_BEATCHAIN_URL"},400);await sb(env,"/rest/v1/beatchain_connections",{method:"POST",headers:{Prefer:"resolution=merge-duplicates,return=minimal"},body:JSON.stringify({user_id:user.id,profile_url:url,display_name:b.display_name||null,updated_at:new Date().toISOString()})});return json({connected:true,profile_url:url});}
async function beatchainStatus(req,env){const user=await currentSupabaseUser(req,env);const c=await sb(env,`/rest/v1/beatchain_connections?select=profile_url,display_name,updated_at&user_id=eq.${encodeURIComponent(user.id)}&limit=1`);return json({connected:Boolean(c.length),connection:c[0]||null});}
export default{async fetch(req,env){if(req.method==="OPTIONS")return new Response(null,{headers:corsHeaders});const u=new URL(req.url);try{if(u.pathname==="/health")return json({ok:true,service:"nexora-api"});if(u.pathname==="/telegram/debug"&&req.method==="GET")return debug(env);if(u.pathname==="/telegram/bot"&&req.method==="GET"){const me=await tg(env,"getMe");return json({username:me.username,name:me.first_name});}if(u.pathname==="/telegram/setup"&&req.method==="POST")return setup(req,env);if(u.pathname==="/telegram/auth/start"&&req.method==="POST"){const b=await req.json(),action=b.action==="register"?"register":"login",challenge=randomToken();await sb(env,"/rest/v1/telegram_auth_challenges",{method:"POST",headers:{Prefer:"return=minimal"},body:JSON.stringify({challenge,action,status:"pending"})});const me=await tg(env,"getMe");return json({challenge,action,bot_username:me.username,deep_link:`https://t.me/${me.username}?start=${challenge}`,expires_in:300});}if(u.pathname==="/telegram/auth/poll"&&req.method==="GET"){const c=u.searchParams.get("challenge");if(!c)return json({error:"challenge is required"},400);const rows=await sb(env,`/rest/v1/telegram_auth_challenges?select=*&challenge=eq.${encodeURIComponent(c)}&limit=1`);if(!rows.length)return json({status:"expired"},404);const r=rows[0];if(new Date(r.expires_at).getTime()<Date.now()&&r.status==="pending"){await patchChallenge(env,c,{status:"expired"});return json({status:"expired"},410);}if(r.status==="pending")return json({status:"pending"});if(r.status==="rejected")return json({status:"rejected"});if(r.status==="approved"){await sb(env,`/rest/v1/telegram_auth_challenges?challenge=eq.${encodeURIComponent(c)}`,{method:"DELETE"});return json({status:"approved",access_token:r.access_token,refresh_token:r.refresh_token,telegram_username:r.telegram_username,display_name:r.display_name});}return json({status:"pending"});}if(u.pathname==="/telegram/webhook"&&req.method==="POST")return webhook(req,env);if(u.pathname==="/soundcloud/connect"&&req.method==="POST")return soundcloudConnect(req,env);if(u.pathname==="/soundcloud/callback"&&req.method==="GET")return soundcloudCallback(req,env);if(u.pathname==="/soundcloud/status"&&req.method==="GET")return soundcloudStatus(req,env);if(u.pathname==="/beatchain/connect"&&req.method==="POST")return beatchainConnect(req,env);if(u.pathname==="/beatchain/status"&&req.method==="GET")return beatchainStatus(req,env);return json({error:"not found"},404);}catch(e){const code=classify(e);console.error("Nexora Worker request failed",{path:u.pathname,code,message:String(e?.message||e)});return json({error:code},code==="AUTH_UNAUTHORIZED"?401:500);}}};
