export function base64url(bytes){let s="";for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");}
export function randomString(n=32){const b=new Uint8Array(n);crypto.getRandomValues(b);return base64url(b);}
export async function sha256Base64Url(value){const d=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(value));return base64url(new Uint8Array(d));}
export async function currentSupabaseUser(req,env){const token=(req.headers.get("Authorization")||"").replace(/^Bearer\s+/i,"");if(!token||!env.SUPABASE_URL||!env.SUPABASE_SERVICE_ROLE_KEY)throw new Error("AUTH_CONFIG_ERROR");const r=await fetch(`${env.SUPABASE_URL}/auth/v1/user`,{headers:{apikey:env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${token}`}});if(!r.ok)throw new Error("AUTH_UNAUTHORIZED");return await r.json();}
export async function scToken(env,body){if(!env.SOUNDCLOUD_CLIENT_ID||!env.SOUNDCLOUD_CLIENT_SECRET||!env.SOUNDCLOUD_REDIRECT_URI)throw new Error("SOUNDCLOUD_CONFIG_MISSING");const form=new URLSearchParams(body);const r=await fetch("https://secure.soundcloud.com/oauth/token",{method:"POST",headers:{accept:"application/json; charset=utf-8","Content-Type":"application/x-www-form-urlencoded"},body:form});const t=await r.text();if(!r.ok)throw new Error(`SOUNDCLOUD_TOKEN_${r.status}:${t}`);return JSON.parse(t);}
export async function scFetch(token,path){const r=await fetch(`https://api.soundcloud.com${path}`,{headers:{accept:"application/json; charset=utf-8",Authorization:`OAuth ${token}`}});const t=await r.text();if(!r.ok)throw new Error(`SOUNDCLOUD_API_${r.status}:${t}`);return t?JSON.parse(t):null;}
